     1	import type { Metadata } from "next";
     2	import { notFound } from "next/navigation";
     3	import { createMetadata } from "@/lib/constants/metadata";
     4	import { createChildLogger } from "@/lib/logger/logger";
     5	import { getCareRecipientProfile } from "@/actions/care-recipient-profile";
     6	import {
     7	  CareGuide,
     8	  loadCareGuide,
     9	  resolveGuideEdition,
    10	  type CareGuideLoadResult,
    11	} from "@/features/consumer/care-guide";
    12	import { careGuideEnabledFlag } from "@/lib/experiments/flags";
    13	
    14	const logger = createChildLogger({ module: "care-guide-page" });
    15	
    16	export const metadata: Metadata = createMetadata({
    17	  title: "Care Guide",
    18	  description: "Your local guide to home care — costs, how to pay, and what to look for.",
    19	  noIndex: true,
    20	});
    21	
    22	export default async function CareGuidePage(): Promise<React.ReactElement> {
    23	  // `notFound()` rather than a redirect so a disabled Care Guide is indistinguishable from a
    24	  // route that was never published — the guide's existence is not something to advertise before
    25	  // it launches.
    26	  //
    27	  // The flag defaults to false, so the route also closes if the backend is unreachable.
    28	  //
    29	  // The gate stays the function's first statement, before any await — putting the profile
    30	  // read, the DMA lookup or the upstream fetch above it would do all three on every
    31	  // production request before notFound() discards them.
    32	  const careGuide = await careGuideEnabledFlag();
    33	  if (!careGuide.value) {
    34	    notFound();
    35	  }
    36	
    37	  const profile = await getCareRecipientProfile({ autoCreate: false });
    38	  const zip = profile.data?.zipCode;
    39	  const { region, reason } = await resolveGuideEdition(zip);
    40	
    41	  // loadCareGuide is defensively exception-safe today (every internal failure resolves to
    42	  // outcome: "unavailable"), but that's this module's own implementation detail, not a contract
    43	  // this page can rely on staying true forever. An unhandled throw here must still hit the error
    44	  // state below, not escape to Next's generic error boundary and undermine the "never a
    45	  // silently-rendered national guide" invariant.
    46	  let loadResult: CareGuideLoadResult;
    47	  try {
    48	    loadResult = await loadCareGuide(region);
    49	  } catch (error) {
    50	    logger.error({ region, reason, error }, "care-guide load threw unexpectedly");
    51	    loadResult = { outcome: "unavailable", guide: null, servedRegion: null, fellBackFrom: null };
    52	  }
    53	  const { outcome, guide, fellBackFrom } = loadResult;
    54	  logger.info({ region, reason, outcome, fellBackFrom }, "care-guide resolved");
    55	
    56	  return (
    57	    // pb-19 (76px) matches BottomNavigation height on mobile; md:pt-26 clears the fixed
    58	    // 80px TopNavigation on desktop. No horizontal max-width/gutters here — CareGuide's hero
    59	    // is full-bleed; CareGuide and the error state below each own their own inner max-width.
    60	    <main className="flex w-full flex-col pb-19 md:pt-26 md:pb-0">
    61	      {outcome === "ok" && guide ? (
    62	        <CareGuide guide={guide} />
    63	      ) : (
    64	        // Interim copy (D7) — final error-state copy is pending content/design input (task 0).
    65	        // Never a silently-rendered national guide: an upstream failure shows this, not content.
    66	        <div className="mx-auto flex w-full max-w-screen-xl flex-col items-center gap-2 px-4 py-16 text-center md:px-8">
    67	          <h1 className="text-2xl font-semibold">We can&apos;t load your care guide right now</h1>
    68	          <p className="text-text-default-caption">Please try again in a few minutes.</p>
    69	        </div>
    70	      )}
    71	    </main>
    72	  );
    73	}

